+export function taskFormat(task: string): 'legacy' | 'v2' | 'invalid' {
+  const header = visibleMarkdown(task).split(/^## /m)[0]!;
+  const markers = [...header.matchAll(/^- TASK 형식:([^\n]*)$/gm)];
+  if (!markers.length) return 'legacy';
